/bin/bash -lc "python3 - <<'PY'
import json
with open('packet.json', encoding='utf-8') as f:
    p=json.load(f)
for line in p['task'].splitlines():
    if line.startswith(('(:Resolution).resolutionScope ', '(:Resolution).resolutionId ', '(:Tdoc).type ', '(:Tdoc).crNumber ', '(:Tdoc)._targetRelease ', '(:Section).specNumber ', '(:Section).sectionNumber ', '(:CR).tdocNumber ', '(:Tdoc).tdocNumber ', '(:CR).id ', '(:Tdoc).id ')):
        print(line)
print('\\nTASK NON-DOMAIN TEXT AFTER DOMAIN HEADING:')
part=p['task'].split('Stored value domains,',1)[1]
for line in part.splitlines():
    if line and not line.startswith('(:'):
        print(line)
print('\\nITEMS 1-40:')
for i, item in enumerate(p['items'][:40],1):
    print(i, item['id'], json.dumps(item['fields']), item['question'])
